function isValid(s) {
  const pair = { ')': '(', ']': '[', '}': '{' };
  const stack = [];
  for (const ch of s) {
    if ('([{'.includes(ch)) stack.push(ch);     // 여는 괄호는 쌓고
    else if (stack.pop() !== pair[ch]) return false; // 닫는 괄호는 짝 확인
  }
  return stack.length === 0;
}

