function nextGreater(nums) {
  const res = Array(nums.length).fill(-1);
  const stack = [];                       // 인덱스를 담는 스택
  for (let i = 0; i < nums.length; i++) {
    while (stack.length && nums[stack.at(-1)] < nums[i]) {
      res[stack.pop()] = nums[i];
    }
    stack.push(i);
  }
  return res;
}

